func (this *Coinspot) ParseBalance(response any) map[string]any {
	var result map[string]any = map[string]any{
		"info": response,
	}
	var balances any = this.SafeValue2(response, "balance", "balances")
	if IsArray(balances) {
		var rows []any = this.ToArray(balances)
		var numRows int = len(rows)
		for i := 0; i < numRows; i++ {
			var currencies map[string]any = SafeMapTyped(rows, i)
			var currencyIdsList []string = nil
			if currencies != nil {
				currencyIdsList = make([]string, 0, len(currencies))
				for objectKey := range currencies {
					currencyIdsList = append(currencyIdsList, objectKey)
				}
			}
			for j := 0; j < len(currencyIdsList); j++ {
				var currencyId string = currencyIdsList[j]
				var balance map[string]any = SafeMapTyped(currencies, currencyId)
				var code *string = this.SafeCurrencyCode(currencyId)
				var account map[string]any = this.Account()
				account["total"] = this.SafeString(balance, "balance")
				if code != nil {
					result[*code] = account
				}
			}
		}
	} else {
		var currencyIdsMap []string = ObjectKeys(balances)
		for i := 0; i < len(currencyIdsMap); i++ {
			var currencyId string = currencyIdsMap[i]
			var code *string = this.SafeCurrencyCode(currencyId)
			var account map[string]any = this.Account()
			account["total"] = this.SafeString(balances, currencyId)
			if code != nil {
				result[*code] = account
			}
		}
	}
	return this.SafeBalance(result).(map[string]any)
}

/**
 * @method
 * @name coinspot#fetchBalance
 * @description query for balance and get the amount of funds available for trading or funds locked in orders
 * @see https://www.coinspot.com.au/api#listmybalance
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
 */
func (this *Coinspot) FetchBalanceAsync(optionalArgs ...any) <-chan AsyncResult[Balances] {
	ch := make(chan AsyncResult[Balances], 1)
	go this.fetchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *Coinspot) fetchBalanceBody(ch chan AsyncResult[Balances], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var method *string = this.SafeString(this.Options, "fetchBalance", "privatePostMyBalances")
	var response map[string]any = nil
	if (method != nil && *method == "private_post_ro_my_balances") || (method != nil && *method == "privatePostRoMyBalances") {

		r1 := <-this.PrivatePostRoMyBalances(params)
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Value
	} else {

		r2 := <-this.PrivatePostMyBalances(params)
		if r2.Err != nil {
			panic(r2.Err)
		}
		response = r2.Value
	}

	//
	// read-write api keys
	//
	//     ...
	//
	// read-only api keys
	//
	//     {
	//         "status":"ok",
	//         "balances":[
	//             {
	//                 "LTC":{"balance":0.1,"audbalance":16.59,"rate":165.95}
	//             }
	//         ]
	//     }
	//
	ch <- AsyncResult[Balances]{Value: BalancesFromMap(this.ParseBalance(response))}
	return nil
}

