/**
 * @method
 * @name coinspot#fetchTicker
 * @description fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market
 * @see https://www.coinspot.com.au/api#latestprices
 * @param {string} symbol unified symbol of the market to fetch the ticker for
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Coinspot) FetchTickerAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[Ticker] {
	ch := make(chan AsyncResult[Ticker], 1)
	go this.fetchTickerBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Coinspot) fetchTickerBody(ch chan AsyncResult[Ticker], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)

	r1 := <-this.PublicGetLatest(params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	var id *string = this.SafeString(market, "id", "")
	id = SafeStringPtr(strings.ToLower(*id))
	var prices map[string]any = SafeMapTyped(response, "prices")
	//
	//     {
	//         "status":"ok",
	//         "prices":{
	//             "btc":{
	//                 "bid":"52732.47000022",
	//                 "ask":"53268.0699976",
	//                 "last":"53284.03"
	//             }
	//         }
	//     }
	//
	var ticker map[string]any = this.SafeDictMap(prices, id, map[string]any{})

	ch <- AsyncResult[Ticker]{Value: this.ParseTicker(ticker, market)}
	return nil
}

/**
 * @method
 * @name coinspot#fetchTickers
 * @description fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market
 * @see https://www.coinspot.com.au/api#latestprices
 * @param {string[]|undefined} symbols unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Coinspot) FetchTickersAsync(optionalArgs ...any) <-chan AsyncResult[map[string]Ticker] {
	ch := make(chan AsyncResult[map[string]Ticker], 1)
	go this.fetchTickersBody(ch, optionalArgs...)
	return ch
}
func (this *Coinspot) fetchTickersBody(ch chan AsyncResult[map[string]Ticker], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}

	r1 := <-this.PublicGetLatest(params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//    {
	//        "status": "ok",
	//        "prices":   {
	//            "btc":   {
	//                "bid": "25050",
	//                "ask": "25370",
	//                "last": "25234"
	//            },
	//            "ltc":   {
	//                "bid": "79.39192993",
	//                "ask": "87.98",
	//                "last": "87.95"
	//            }
	//        }
	//    }
	//
	var result map[string]any = map[string]any{}
	var prices map[string]any = SafeMapTyped(response, "prices")
	var ids []string = nil
	if prices != nil {
		ids = make([]string, 0, len(prices))
		for objectKey := range prices {
			ids = append(ids, objectKey)
		}
	}
	for i := 0; i < len(ids); i++ {
		var id string = ids[i]
		var market map[string]any = this.SafeMarket(id)
		if market["spot"] == true {
			var symbol *string = SafeStringPtr(market["symbol"])
			var ticker any = prices[id]
			if symbol != nil {
				result[*symbol] = TickerToMap(this.ParseTicker(ticker, market))
			}
		}
	}

	ch <- AsyncResult[map[string]Ticker]{Value: TickerMapFromMap(this.FilterByArrayTickers(result, "symbol", symbols))}
	return nil
}

