/**
 * @method
 * @name coinspot#fetchMyTrades
 * @description fetch all trades made by the user
 * @see https://www.coinspot.com.au/api#rotransaction
 * @param {string} symbol unified market symbol
 * @param {int} [since] the earliest time in ms to fetch trades for
 * @param {int} [limit] the maximum number of trades structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {Trade[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=trade-structure}
 */
func (this *Coinspot) FetchMyTradesAsync(optionalArgs ...any) <-chan AsyncResult[[]Trade] {
	ch := make(chan AsyncResult[[]Trade], 1)
	go this.fetchMyTradesBody(ch, optionalArgs...)
	return ch
}
func (this *Coinspot) fetchMyTradesBody(ch chan AsyncResult[[]Trade], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	since := GetArg(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var request map[string]any = map[string]any{}
	var market map[string]any = nil
	if symbol != nil {
		market = this.Market(symbol)
	}
	if since != nil {
		request["startdate"] = this.Yyyymmdd(since)
	}

	r1 := <-this.PrivatePostRoMyTransactions(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//  {
	//      "status": "ok",
	//      "buyorders": [
	//          {
	//              "otc": false,
	//              "market": "ALGO/AUD",
	//              "amount": 386.95197925,
	//              "created": "2022-10-20T09:56:44.502Z",
	//              "audfeeExGst": 1.80018002,
	//              "audGst": 0.180018,
	//              "audtotal": 200
	//          },
	//      ],
	//      "sellorders": [
	//          {
	//              "otc": false,
	//              "market": "SOLO/ALGO",
	//              "amount": 154.52345614,
	//              "total": 115.78858204658796,
	//              "created": "2022-04-16T09:36:43.698Z",
	//              "audfeeExGst": 1.08995731,
	//              "audGst": 0.10899573,
	//              "audtotal": 118.7
	//          },
	//      ]
	// }
	var buyTrades []any = SafeListTypedDefault(response, "buyorders", []any{})
	for i := 0; i < len(buyTrades); i++ {
		AddElementToObject(buyTrades[i], "side", "buy")
	}
	var sellTrades []any = SafeListTypedDefault(response, "sellorders", []any{})
	for i := 0; i < len(sellTrades); i++ {
		AddElementToObject(sellTrades[i], "side", "sell")
	}
	var trades []any = this.ArrayConcat(buyTrades, sellTrades)

	ch <- AsyncResult[[]Trade]{Value: TradesFromList(this.ParseTrades(trades, market, since, limit))}
	return nil
}
func (this *Coinspot) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	// public fetchTrades
	//
	//     {
	//         "amount":0.00102091,
	//         "rate":21549.09999991,
	//         "total":21.99969168,
	//         "coin":"BTC",
	//         "solddate":1604890646143,
	//         "market":"BTC/AUD"
	//     }
	//
	// private fetchMyTrades
	//     {
	//       "otc": false,
	//       "market": "ALGO/AUD",
	//       "amount": 386.95197925,
	//       "created": "2022-10-20T09:56:44.502Z",
	//       "audfeeExGst": 1.80018002,
	//       "audGst": 0.180018,
	//       "audtotal": 200,
	//       "total": 200,
	//       "side": "buy",
	//       "price": 0.5168600000125209
	//     }
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = nil
	var priceString *string = nil
	var fee map[string]any = nil
	var audTotal *string = this.SafeString(trade, "audtotal")
	var costString *string = this.SafeString(trade, "total", audTotal)
	var side *string = this.SafeString(trade, "side")
	var amountString *string = this.SafeString(trade, "amount")
	var marketId *string = this.SafeString(trade, "market")
	var symbol *string = this.SafeSymbol(marketId, market, "/")
	var solddate *int64 = this.SafeInteger(trade, "solddate")
	if solddate != nil {
		priceString = this.SafeString(trade, "rate")
		timestamp = solddate
	} else {
		priceString = Precise.StringDiv(costString, amountString)
		var createdString *string = this.SafeString(trade, "created")
		timestamp = this.Parse8601(createdString)
		var audfeeExGst *string = this.SafeString(trade, "audfeeExGst")
		var audGst *string = this.SafeString(trade, "audGst")
		// The transaction fee which consumers pay is inclusive of GST by default
		var feeCost *string = Precise.StringAdd(audfeeExGst, audGst)
		var feeCurrencyId string = "AUD"
		fee = map[string]any{
			"cost":     this.ParseNumber(feeCost),
			"currency": this.SafeCurrencyCode(feeCurrencyId),
		}
	}
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"id":           nil,
		"symbol":       symbol,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"order":        nil,
		"type":         nil,
		"side":         side,
		"takerOrMaker": nil,
		"price":        this.ParseNumber(priceString),
		"amount":       this.ParseNumber(amountString),
		"cost":         this.ParseNumber(costString),
		"fee":          fee,
	}, market)
}

/**
 * @method
 * @name coinspot#createOrder
 * @description create a trade order
 * @see https://www.coinspot.com.au/api#placebuyorder
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type must be 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Coinspot) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Coinspot) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	this.CheckRequiredArgument("createOrder", side, "side")
	var sideUpper string = strings.ToUpper(side)
	if typeVar == "market" {
		panic(ExchangeError(this.Id + " createOrder() allows limit orders only"))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"cointype": market["id"],
		"amount":   amount,
		"rate":     price,
	}
	var response map[string]any = nil
	if sideUpper == "BUY" {

		r1 := <-this.PrivatePostMyBuy(this.Extend(request, params))
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Value
	} else if sideUpper == "SELL" {

		r2 := <-this.PrivatePostMySell(this.Extend(request, params))
		if r2.Err != nil {
			panic(r2.Err)
		}
		response = r2.Value
	} else {
		panic(NotSupported(this.Id + " createOrder only support buy/sell side"))
	}

	//
	// status - ok, error
	//
	ch <- AsyncResult[Order]{Value: this.SafeOrder(map[string]any{
		"info": response,
	})}
	return nil
}

/**
 * @method
 * @name coinspot#cancelOrder
 * @description cancels an open order
 * @see https://www.coinspot.com.au/api#cancelbuyorder
 * @see https://www.coinspot.com.au/api#cancelsellorder
 * @param {string} id order id
 * @param {string} symbol not used by cancelOrder ()
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} An [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Coinspot) CancelOrderAsync(id any, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.cancelOrderBody(ch, id, optionalArgs...)
	return ch
}
func (this *Coinspot) cancelOrderBody(ch chan AsyncResult[Order], id any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	var side *string = this.SafeString(params, "side")
	if (side == nil || *side != "buy") && (side == nil || *side != "sell") {
		panic(ArgumentsRequired(this.Id + " cancelOrder() requires a side parameter, \"buy\" or \"sell\""))
	}
	var paramsOmitted map[string]any = this.OmitDict(params, "side")
	var request map[string]any = map[string]any{
		"id": id,
	}
	var response map[string]any = nil
	if side != nil && *side == "buy" {

		r := <-this.PrivatePostMyBuyCancel(this.Extend(request, paramsOmitted))
		if r.Err != nil {
			panic(r.Err)
		}
		response = r.Value
	} else {

		r1 := <-this.PrivatePostMySellCancel(this.Extend(request, paramsOmitted))
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Value
	}

	//
	// status - ok, error
	//
	ch <- AsyncResult[Order]{Value: this.SafeOrder(map[string]any{
		"info": response,
	})}
	return nil
}
func (this *Coinspot) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if response == nil {
		return nil // fallback to default error handler
	}
	var status *string = this.SafeString(response, "status")
	if status != nil && *status == "error" {
		var feedback string = this.Id + " " + this.Json(response)
		panic(ExchangeError(feedback))
	}
	return nil
}
func (this *Coinspot) Nonce() int64 {
	// the venue accepts any strictly-increasing integer, so use milliseconds: with the second-resolution base nonce a burst of N calls would leave incrementingNonce N seconds ahead of the clock
	return this.Milliseconds()
}
func (this *Coinspot) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var requestHeaders map[string]any = nil
	var requestBody any = nil
	var apiLength int = len(api)
	var isVersionedApi bool = (apiLength > 1)
	var accessType string = api[0]
	if isVersionedApi {
		accessType = api[1]
	}
	var endpoint string = "/" + this.ImplodeParams(path, params)
	var fullPath string = endpoint
	if isVersionedApi {
		fullPath = "/" + api[0] + endpoint
	}
	var apiUrl *string = this.SafeString(this.Urls["api"], accessType)
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url string = *apiUrl + fullPath
	if accessType == "private" {
		this.CheckRequiredCredentials()
		// coinspot requires an increasing nonce
		var nonce int64 = this.IncrementingNonce()
		requestBody = this.Json(this.Extend(map[string]any{
			"nonce": nonce,
		}, params))
		requestHeaders = map[string]any{
			"Content-Type": "application/json",
			"key":          this.ApiKey,
			"sign":         this.Hmac(this.Encode(requestBody), this.Encode(this.Secret), sha512),
		}
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    requestBody,
		"headers": requestHeaders,
	}
}

func NewCoinspot(userConfig map[string]any) *Coinspot {
	p := newCoinspot()
	p.Init(userConfig)
	return p
}

func (this *Coinspot) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

